package com.ecoriego.app.data;
import android.content.*; import android.database.*; import android.database.sqlite.*; import com.ecoriego.app.model.*; import java.util.*;
public class DBHelper extends SQLiteOpenHelper {
 private static final String DB="ecoriego.db"; private static final int VER=1;
 public DBHelper(Context c){super(c,DB,null,VER);}
 @Override public void onConfigure(SQLiteDatabase db){super.onConfigure(db);db.setForeignKeyConstraintsEnabled(true);} @Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE plantas (id_planta INTEGER PRIMARY KEY AUTOINCREMENT,nombre TEXT NOT NULL,especie TEXT NOT NULL,fecha_siembra TEXT NOT NULL,frecuencia_riego_dias INTEGER NOT NULL,ubicacion TEXT NOT NULL,notas TEXT)");db.execSQL("CREATE TABLE bitacora_riego (id_riego INTEGER PRIMARY KEY AUTOINCREMENT,planta_id INTEGER NOT NULL,fecha_hora TEXT NOT NULL,temperatura_momento REAL NOT NULL,llovio INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(planta_id) REFERENCES plantas(id_planta) ON DELETE CASCADE)");}
 @Override public void onUpgrade(SQLiteDatabase db,int oldV,int newV){db.execSQL("DROP TABLE IF EXISTS bitacora_riego");db.execSQL("DROP TABLE IF EXISTS plantas");onCreate(db);}
 public long insertarPlanta(Planta p){SQLiteDatabase db=getWritableDatabase();ContentValues v=cv(p);return db.insert("plantas",null,v);}
 public int actualizarPlanta(Planta p){SQLiteDatabase db=getWritableDatabase();return db.update("plantas",cv(p),"id_planta=?",new String[]{String.valueOf(p.getId())});}
 public int eliminarPlanta(int id){SQLiteDatabase db=getWritableDatabase();return db.delete("plantas","id_planta=?",new String[]{String.valueOf(id)});}
 private ContentValues cv(Planta p){ContentValues v=new ContentValues();v.put("nombre",p.getNombre());v.put("especie",p.getEspecie());v.put("fecha_siembra",p.getFechaSiembra());v.put("frecuencia_riego_dias",p.getFrecuencia());v.put("ubicacion",p.getUbicacion());v.put("notas",p.getNotas());return v;}
 public List<Planta> listarPlantas(){List<Planta> l=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT * FROM plantas ORDER BY nombre ASC",null);while(c.moveToNext())l.add(from(c));c.close();return l;}
 public Planta obtenerPlanta(int id){Cursor c=getReadableDatabase().rawQuery("SELECT * FROM plantas WHERE id_planta=?",new String[]{String.valueOf(id)});Planta p=c.moveToFirst()?from(c):null;c.close();return p;}
 private Planta from(Cursor c){return new Planta(c.getInt(c.getColumnIndexOrThrow("id_planta")),c.getString(c.getColumnIndexOrThrow("nombre")),c.getString(c.getColumnIndexOrThrow("especie")),c.getString(c.getColumnIndexOrThrow("fecha_siembra")),c.getInt(c.getColumnIndexOrThrow("frecuencia_riego_dias")),c.getString(c.getColumnIndexOrThrow("ubicacion")),c.getString(c.getColumnIndexOrThrow("notas")));}
 public long registrarRiego(int plantaId,double temp,boolean lluvia){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("planta_id",plantaId);v.put("fecha_hora",new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.getDefault()).format(new Date()));v.put("temperatura_momento",temp);v.put("llovio",lluvia?1:0);long id=db.insertOrThrow("bitacora_riego",null,v);db.setTransactionSuccessful();return id;}catch(Exception e){return -1;}finally{db.endTransaction();}}
 public List<Riego> riegosDePlanta(int id){List<Riego> l=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT * FROM bitacora_riego WHERE planta_id=? ORDER BY fecha_hora DESC",new String[]{String.valueOf(id)});while(c.moveToNext())l.add(riego(c));c.close();return l;}
 private Riego riego(Cursor c){return new Riego(c.getInt(c.getColumnIndexOrThrow("id_riego")),c.getInt(c.getColumnIndexOrThrow("planta_id")),c.getString(c.getColumnIndexOrThrow("fecha_hora")),c.getDouble(c.getColumnIndexOrThrow("temperatura_momento")),c.getInt(c.getColumnIndexOrThrow("llovio"))==1);}
 public int totalRiegos(){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM bitacora_riego",null);int n=c.moveToFirst()?c.getInt(0):0;c.close();return n;}
 public List<String> masRegadas(){List<String> l=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT p.nombre, COUNT(r.id_riego) total FROM plantas p LEFT JOIN bitacora_riego r ON p.id_planta=r.planta_id GROUP BY p.id_planta,p.nombre ORDER BY total DESC LIMIT 5",null);while(c.moveToNext())l.add(c.getString(0)+"  ·  "+c.getInt(1)+" riegos");c.close();return l;}
 public List<String> pendientes(){List<String> l=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT p.nombre, p.frecuencia_riego_dias, MAX(r.fecha_hora) ultima FROM plantas p LEFT JOIN bitacora_riego r ON p.id_planta=r.planta_id GROUP BY p.id_planta,p.nombre,p.frecuencia_riego_dias ORDER BY p.nombre",null);long now=System.currentTimeMillis();while(c.moveToNext()){String last=c.getString(2);boolean due=last==null;try{if(!due){Date d=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.getDefault()).parse(last);due=now-d.getTime()>=c.getInt(1)*86400000L;}}catch(Exception e){}if(due)l.add("• "+c.getString(0)+"  ·  necesita riego");}c.close();return l;}
 public List<Riego> historial(){List<Riego> l=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT * FROM bitacora_riego ORDER BY fecha_hora DESC LIMIT 30",null);while(c.moveToNext())l.add(riego(c));c.close();return l;}
 public List<String> historialNombres(){List<String> l=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT p.nombre,r.fecha_hora,r.temperatura_momento,r.llovio FROM bitacora_riego r JOIN plantas p ON p.id_planta=r.planta_id ORDER BY r.fecha_hora DESC LIMIT 30",null);while(c.moveToNext())l.add(c.getString(0)+"  ·  "+c.getString(1)+"  ·  "+String.format(Locale.getDefault(),"%.1f°C",c.getDouble(2))+"  ·  "+(c.getInt(3)==1?"lluvia":"sin lluvia"));c.close();return l;}
}
